    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError("imp_user must be a string")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dictionary")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dictionary")
    if handlers is not None and not isinstance(handlers, dict):
        raise ValueError("handlers must be a dictionary")

def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or a float")
    if n == int(n):
        return n
    if n % 1 == 0.5:
        return int(n + 0.5)
    return round(n)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            if len(args) != len(fields):
                raise ValueError("Number of arguments does not match the number of fields")
            for field, value in zip(fields, args):
                setattr(self, field, value)
            if 'srid' in kwargs:
                self.srid = kwargs['srid']
            else:
                self.srid = srid_map.get(name, 0)

        def __repr__(self):
            return f"Point({', '.join(f'{field}={getattr(self, field)}' for field in fields)})"

    return Point

