def parse_version(s: str) -> tuple[int, ...]:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    parts = s.split('.')
    if len(parts) != 3:
        raise ValueError("Version string must have exactly three parts separated by dots")
    try:
        return tuple(int(part) for part in parts)
    except ValueError:
        raise ValueError("Invalid version part")

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not all(isinstance(item, str) for item in cmd):
        raise ValueError("All elements in the command tuple must be strings")

    normalized_cmd = []
    for item in cmd:
        if item.startswith('#!'):
            normalized_cmd.append(item.replace('#!', ''))
        else:
            normalized_cmd.append(item)

    return tuple(normalized_cmd)

def cached(cache, key=hashkey, lock=None):
    def wrapper(func):
        def memoized_func(*args, **kwargs):
            if key is not None:
                key_value = key(*args, **kwargs)
            else:
                key_value = args
            if key_value in cache:
                return cache[key_value]
            else:
                result = func(*args, **kwargs)
                cache[key_value] = result
                return result
        return memoized_func
    return wrapper

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = OrderedDict()
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            if timer() - cache[key][1] > ttl:
                del cache[key]
            else:
                return cache[key][0]
        result = func(*args, **kwargs)
        if len(cache) >= maxsize:
            cache.popitem(last=False)
        cache[key] = (result, timer())
        return result
    return wrapper

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    @lru_cache(maxsize=maxsize, typed=typed)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def lfu_cache(maxsize=128, typed=False):
    cache = OrderedDict()
    hits = 0
    misses = 0

    def wrapper(*args, **kwargs):
        nonlocal hits, misses
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            cache.move_to_end(key)
            hits += 1
            return cache[key]
        else:
            misses += 1
            if len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = args, frozenset(kwargs.items())
            return args, frozenset(kwargs.items())

    return wrapper

