def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        cache_key = key(func, *func.__args__, **func.__kwds__)
        if cache_key in cache:
            return cache[cache_key]
        else:
            result = func(*func.__args__, **func.__kwds__)
            cache[cache_key] = result
            return result
    return decorator

def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("Input must be an exception instance")
    if max_level < 1:
        raise ValueError("max_level must be at least 1")
    if max_path_level < 1:
        raise ValueError("max_path_level must be at least 1")
    try:
        stack = traceback.extract_stack(limit=max_level)
        path = traceback.extract_tb(e.__traceback__, limit=max_path_level)
        formatted_stack = []
        for frame in stack:
            formatted_stack.append(f"{frame.filename}:{frame.lineno} - {frame.name}")
        for frame in path:
            formatted_stack.append(f"{frame.filename}:{frame.lineno} - {frame.name}")
        return "\n".join(formatted_stack)
    except Exception as e:
        return f"Error formatting exception: {e}"

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    try:
        if overwrite:
            with open(file_name, 'w', encoding=encoding) as file:
                file.write(text_buffer)
        else:
            with open(file_name, 'a', encoding=encoding) as file:
                file.write(text_buffer)
        return len(text_buffer)
    except Exception as e:
        print(f"An error occurred: {e}")
        return -1

def file_to_textbuffer(file_name, encoding):
    try:
        with open(file_name, 'r', encoding=encoding) as file:
            return file.read()
    except FileNotFoundError:
        print(f"File '{file_name}' not found.")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

