def _legacy_mergeOrderings(orderings):
    if not all(isinstance(ordering, list) for ordering in orderings):
        raise ValueError("All orderings must be lists")

    merged_ordering = []
    seen_objects = set()

    for ordering in orderings:
        for obj in ordering:
            if obj in seen_objects:
                merged_ordering.extend(ordering[ordering.index(obj):])
            else:
                seen_objects.add(obj)
                merged_ordering.append(obj)

    return merged_ordering

def _normalizeargs(sequence, output=None):
    if not isinstance(sequence, (list, tuple)):
        raise ValueError("Input must be a list or tuple")
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(item)
        elif isinstance(item, Interface):
            output.append(item)
        else:
            raise ValueError("Invalid item in sequence")
    return output

