def is_fill_request_el(obj):
    if not hasattr(obj, 'fill') or not hasattr(obj, 'request'):
        raise ValueError("Object must contain 'fill' and 'request' methods.")
    return True

def is_run_el(obj):
    if not hasattr(obj, 'run'):
        raise ValueError("Object does not contain an executable method 'run'")
    return True

def is_fill_compute_el(obj):
    if not hasattr(obj, 'fill') or not hasattr(obj, 'compute'):
        raise ValueError("Object must contain executable methods 'fill' and 'compute'")
    return True

def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    elif level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict) and isinstance(d2[k], dict):
                result[k] = difference(v, d2[k], level - 1)
            elif v != d2[k]:
                result[k] = v
        return result

def fill(self, coord, weight=1):
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Invalid coordinate format. Expected a tuple of two integers.")
    if not isinstance(weight, (int, float)):
        raise ValueError("Invalid weight format. Expected an integer or float.")
    if not self.is_valid_coord(coord):
        raise ValueError("Coordinate is out of the histogram edges.")
    self.histogram[coord] += weight

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")
    if not isinstance(first_level, bool):
        raise ValueError("first_level must be a boolean")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, list):
            observer_schema[key] = [None] * len(value)
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level)
        else:
            observer_schema[key] = None

    if first_level:
        # Copy identifying fields from the manifest file
        observer_schema['apiVersion'] = manifest_dict.get('apiVersion')
        observer_schema['kind'] = manifest_dict.get('kind')
        observer_schema['metadata'] = manifest_dict.get('metadata', {})

    return observer_schema

