                raise ValueError("Invalid in_style: %s" % self.SQLParams.in_style)
        else:
            raise TypeError("params must be a dict or a list/tuple")

    return formatted_sql, converted_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Check if the path exists
        if not os.path.exists(path):
            return False

        # Check if the path is a directory
        if not os.path.isdir(path):
            return False

        # Check if the directory contains the necessary files
        required_files = ['metadata.json', 'content']
        for file in required_files:
            if not os.path.exists(os.path.join(path, file)):
                return False

        return True
    except Exception as e:
        print(f"An error occurred: {e}")
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string")
    return f"{prefix}Validator status: {self.status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string")
    if not isinstance(self, ValidationLog):
        raise ValueError("self must be an instance of ValidationLog")
    return f"{prefix}{self.log}"

def validate(self, inventory, extract_spec_version=False):
    if not inventory:
        raise ValueError("Inventory cannot be None")
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")
    if extract_spec_version:
        if 'type' not in inventory:
            raise ValueError("Inventory must contain a 'type' key")
        if inventory['type'] not in self.spec_version:
            raise ValueError("Invalid type value in inventory")
    else:
        if 'version' not in inventory:
            raise ValueError("Inventory must contain a 'version' key")
        if inventory['version'] not in self.spec_version:
            raise ValueError("Invalid version value in inventory")

def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, list) or not all(isinstance(file, str) for file in manifest_files):
        raise ValueError("Manifest files must be a list of strings.")
    if not isinstance(digests_used, list) or not all(isinstance(digest, str) for digest in digests_used):
        raise ValueError("Digests used must be a list of strings.")

    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in the manifest files.")

    for file in manifest_files:
        if file not in digests_used:
            raise ValueError(f"File {file} is not used in the digests used.")

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object")
    if not self.is_valid():
        raise ValueError("self inventory is not valid")
    if not prior.is_valid():
        raise ValueError("prior inventory is not valid")
    if not self.is_prior_version(prior):
        raise ValueError("prior is not a valid prior version of the current inventory object")

def get_logical_path_map(inventory, version):
    if not inventory or not version:
        raise ValueError("Inventory and version cannot be None")

    logical_path_map = {}
    for state in inventory:
        logical_path = state['logical_path']
        content_files = set()
        for file in state['files']:
            if file['version'] == version:
                content_files.add(file['path'])
            elif file['version'] > version:
                content_files.add(file['path'] + f" (duplicate in version {file['version']})")
        logical_path_map[logical_path] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    if not fixity or not manifest_files:
        raise ValueError("Fixity and manifest files must be provided.")

    if not isinstance(fixity, dict):
        raise TypeError("Fixity must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise TypeError("Manifest files must be a list.")

    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File {file} is not listed in the manifest.")

