def add_rendition(self, lang, file_path):
    if not isinstance(lang, str) or not isinstance(file_path, str):
        raise ValueError("Both lang and file_path must be strings.")
    if not file_path.endswith('.pdf'):
        raise ValueError("File path must end with '.pdf'.")
    # Add logic to generate the rendition file path
    rendition_file_path = f"{file_path.split('.')[0]}-{lang}.pdf"
    return rendition_file_path

def add_asset(self, basename, file_path):
    if not basename or not file_path:
        raise ValueError("Both basename and file_path must be provided.")
    if not basename.endswith('.tiff') and not basename.endswith('.jpg') and not basename.endswith('.png'):
        raise ValueError("Invalid file extension. Only .tiff, .jpg, and .png are allowed.")
    if not os.path.exists(file_path):
