def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, tuple):
            a, b = arg
            if a == b:
                result.append(a)
            elif a == ~b:
                result.append(a & b)
            elif b == ~a:
                result.append(a | b)
        else:
            result.append(arg)
    return result

