def size_to_bytes(size: str) -> int:
    size = size.upper()
    if not size.endswith(('K', 'M', 'G')):
        raise ValueError("Invalid file size format. Please use 'K', 'M', or 'G' suffix.")

    size = size[:-1]
    multiplier = {'K': 1024, 'M': 1024**2, 'G': 1024**3}

    try:
        return int(size) * multiplier[size[-1]]
    except ValueError:
        raise ValueError("Invalid file size value.")

