def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 'posix' if re.match(r'^[a-zA-Z0-9_]+$', platform) else 'cmd'
    elif platform not in ['posix', 'cmd']:
        raise ValueError("Invalid platform value. Use 'this', 1, or 0.")

    if platform == 'posix':
        return re.split(r'[\s\t]+', s)
    elif platform == 'cmd':
        return re.split(r'[\s]+', s)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit == "weeks":
            return datetime.timedelta(weeks=number)
        elif unit == "days":
            return datetime.timedelta(days=number)
        elif unit == "hours":
            return datetime.timedelta(hours=number)
        elif unit == "minutes":
            return datetime.timedelta(minutes=number)
        elif unit == "seconds":
            return datetime.timedelta(seconds=number)
        else:
            raise ValueError(f"Unsupported unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Invalid frequency: {frequency}. {e}")

