def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not isinstance(hist, np.ndarray) or not np.issubdtype(hist.dtype, np.number):
        raise ValueError("hist must contain only numeric bins (without context)")

    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if scale is True:
        scale = hist

    if len(field_names) != hist.ndim:
        raise ValueError("field_names must have the same number of elements as the dimension of the result")

    graph = np.zeros((hist.shape[0], len(field_names)), dtype=np.float64)

    for i, bin_ in enumerate(hist):
        if make_value is not None:
            bin_ = make_value(bin_)
        if get_coordinate == "left":
            graph[i, 0] = bin_[0]
            graph[i, 1] = bin_[1]
            graph[i, 2] = bin_[2]
        elif get_coordinate == "right":
            graph[i, 0] = bin_[0]
            graph[i, 1] = bin_[1]
            graph[i, 2] = bin_[2]
        elif get_coordinate == "middle":
            graph[i, 0] = bin_[0]
            graph[i, 1] = bin_[1]
            graph[i, 2] = bin_[2]

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True  # Skip the providedBy check if tentative

    if not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Interface {iface} not provided by {candidate}")

    for method in iface.implementedBy(candidate):
        if not hasattr(candidate, method):
            raise zope.interface.Invalid(f"Method {method} not found in {candidate}")

    for attr in iface.providedBy(candidate):
        if not hasattr(candidate, attr):
            raise zope.interface.Invalid(f"Attribute {attr} not found in {candidate}")

    return True

def verifyObject(iface, candidate, tentative=False):
    if tentative:
        return True  # Skip the providedBy check if tentative

    if not iface.providedBy(candidate):
        raise Invalid(f"Interface {iface} not provided by {candidate}")

    for method_name in iface.implementedBy(candidate):
        method = getattr(candidate, method_name)
        if not callable(method):
            raise Invalid(f"Method {method_name} is not callable in {candidate}")

    for attr_name in iface.providedBy(candidate):
        attr = getattr(candidate, attr_name)
        if not hasattr(attr, '__get__'):
            raise Invalid(f"Attribute {attr_name} is not a property in {candidate}")

    return True

def verifyClass(iface, candidate, tentative=False):
    if not isinstance(iface, type):
        raise TypeError("iface must be a type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a type")
    if tentative and not hasattr(candidate, iface.__name__):
        raise AttributeError(f"{candidate.__name__} does not have attribute {iface.__name__}")
    return True

def determineMetaclass(bases, explicit_mc=None):
    if not bases:
        raise ValueError("bases must not be empty")
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("explicit_mc must be a type")
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__
    return object

def pop(self, key, default=__marker):
    if key not in self._data:
        if default is __marker:
            raise KeyError(f"Key {key} not found in the dictionary")
        return default
    return self._data.pop(key)

