def isoparse(dt_str):
    try:
        dt = dateutil.parser.parse(dt_str)
        return dt
    except ValueError as e:
        raise ValueError(f"Invalid ISO-8601 datetime string: {dt_str}. Error: {e}")

def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    try:
        if isinstance(timestr, datetime):
            if default is not None and isinstance(default, datetime):
                timestr = default
            elif default is not None:
                raise TypeError("default must be a datetime object or None")
        elif not isinstance(timestr, str):
            raise TypeError("timestr must be a string or character stream")
        else:
            timestr = timestr.strip()
            if not timestr:
                return default if default is not None else None

        if ignoretz:
            tzinfo = None
        else:
            if tzinfos is None:
                tzinfos = {}
            elif callable(tzinfos):
                tzinfo = tzinfos(timestr, None)
            else:
                tzinfo = tzinfos.get(timestr, None)

        if tzinfo is None:
            raise ValueError("Invalid tzinfo")

        return parse(timestr, tzinfo=tzinfo, **kwargs)
    except Exception as e:
        raise ParserError(str(e))

