def format_dt(dt):
    if not isinstance(dt, datetime):
        raise ValueError("Input must be a datetime object")
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    current_tag = None

    for char in text:
        if char == '<':
            in_code_block = True
            current_tag = None
        elif char == '>':
            if in_code_block:
                if current_tag:
                    tags.add(current_tag)
                in_code_block = False
                current_tag = None
        elif in_code_block:
            if current_tag is None:
                current_tag = char
            else:
                current_tag += char

    if replacer:
        for tag in tags:
            text = text.replace(tag, replacer(tag))

    return tags, text

def fetch_content_type(url: str) -> Optional[str]:
    try:
        response = requests.head(url)
        return response.headers.get('content-type')
    except requests.exceptions.RequestException as e:
        print(f"Error fetching content type: {e}")
        return None

def test_tag(tag: str) -> bool:
    if not isinstance(tag, str):
        raise ValueError("Input must be a string")
    if len(tag) < 2 or len(tag) > 20:
        raise ValueError("Tag length must be between 2 and 20 characters")
    if not tag.isalnum():
        raise ValueError("Tag must contain only alphanumeric characters")
    return True

def xml_children_as_dict(node):
    if not node or not node.children:
        return {}
    children_dict = {}
    for child in node.children:
        children_dict[child.tag] = child.text
    return children_dict

