        raise ValueError("The second argument must be a string.")
    if not isinstance(val, (int, float, str, list, dict)):
        raise ValueError("The third argument must be a value.")
    if not keys:
        raise ValueError("At least one key must be provided.")

    current_dict = dic
    for k in keys[:-1]:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]

    current_dict[keys[-1]] = val

