def validate_min_max_args(self, args):
    if not isinstance(args, dict):
        raise ValueError("Input must be a dictionary")
    if 'min' not in args or 'max' not in args:
        raise ValueError("Dictionary must contain 'min' and 'max' keys")
    if not isinstance(args['min'], (int, float)) or not isinstance(args['max'], (int, float)):
        raise ValueError("Values of 'min' and 'max' must be numbers")
    if 'value' not in args:
        raise ValueError("Dictionary must contain 'value' key")
    if not isinstance(args['value'], (int, float)):
